test "symmetric buffer layout matches build_symm_buffer_layout" {
    for (buffers_gt) |g| {
        const T = L.alignTokens(@intCast(g[3]));
        try std.testing.expectEqual(g[4], T);
        const shape: L.Shape = .{
            .num_ranks = @intCast(g[1]),
            .num_experts = @intCast(g[2]),
            .num_topk = @intCast(g[5]),
            .hidden = @intCast(g[6]),
            .intermediate_hidden = @intCast(g[7]),
            .num_shared_experts = @intCast(g[8]),
            .num_max_tokens_per_rank = T,
        };
        const lay: L.SymmBufferLayout = .init(shape, @intCast(g[0]));
        const b = lay.buffer;
        const l = g[9..30];
        try std.testing.expectEqual(l[0], lay.numBytes());
        try std.testing.expectEqual(l[1], b.input_token.offset);
        try std.testing.expectEqual(l[2], b.input_sf.offset);
