        try std.testing.expectEqual(l[11], b.l2_sf.offset);
        try std.testing.expectEqual(l[13], T);
        try std.testing.expectEqual(l[18], shape.sharedIntermediateHidden());
        try std.testing.expectEqual(l[19], lay.num_ring_tokens);
        try std.testing.expectEqual(l[20], lay.num_sf_ring_tokens);
        try std.testing.expectEqual(g[30], b.workspace.numBytes());
        try std.testing.expectEqual(g[31], b.workspace.num_max_pool_tokens);
        try std.testing.expectEqual(g[32], b.workspace.num_shared_l2_pool_blocks);
        try std.testing.expectEqual(g[33], L.numMaxSharedSfTokens(T));
    }
}

